export type AdvancedQuestion = { prompt:string; options:string[]; answer:number; why:string; code?:string };
export type AdvancedStep = { id:string; title:string; summary:string; code:string; questions:AdvancedQuestion[] };

type Definition = { id:string; title:string; summary:string; code:string; correct:string; wrong:string[]; why:string };

const legacyPrompts = [
  () => `¿Cuál afirmación describe correctamente este concepto?`,
  () => `En el contexto de este concepto, ¿cuál opción es válida?`,
  () => `¿Qué resultado o comportamiento esperarías en este tema?`,
  (d:Definition) => `¿Cuál es la trampa común sobre ${d.title.toLowerCase()}?`,
  (d:Definition) => `¿Qué decisión de diseño corresponde a ${d.title.toLowerCase()}?`,
  () => `¿Qué palabra, tipo o API se relaciona directamente con este tema?`,
  (d:Definition) => `¿Qué alternativa NO sería correcta para ${d.title.toLowerCase()}?`,
  () => `Si ves el código del ejemplo, ¿qué concepto estás aplicando?`,
  (d:Definition) => `¿Qué afirmación de entrevista es correcta sobre ${d.title.toLowerCase()}?`,
  (d:Definition) => `¿Qué deberías recordar para evitar un bug en ${d.title.toLowerCase()}?`,
];

void legacyPrompts;

const specificPrompts = [
  (d:Definition) => `Lee este ejemplo de ${d.title}: \`${d.code.split("\\n")[0]}\`. ¿Qué comportamiento describe correctamente el código?`,
  (d:Definition) => `Para el código de ${d.title}, ¿qué opción explica el papel de la parte principal del ejemplo?`,
  (d:Definition) => `Si ejecutaras el ejemplo de ${d.title}, ¿qué resultado o efecto deberías esperar?`,
  (d:Definition) => `En ${d.title}, ¿qué error común produciría un código como el mostrado?`,
  (d:Definition) => `Si tuvieras que aplicar ${d.title} en una clase real, ¿qué decisión sería la adecuada?`,
  (d:Definition) => `¿Qué palabra, tipo o API del ejemplo de ${d.title} está directamente relacionada con la solución?`,
  (d:Definition) => `¿Qué alternativa sería incorrecta al implementar ${d.title} como muestra el ejemplo?`,
  (d:Definition) => `A partir del código de ${d.title}, ¿qué concepto concreto se está aplicando?`,
  (d:Definition) => `En una entrevista sobre ${d.title}, ¿qué afirmación defenderías con este ejemplo?`,
  (d:Definition) => `¿Qué regla de ${d.title} deberías recordar para evitar un bug en este código?`,
];

function makeQuestions(d:Definition):AdvancedQuestion[] {
  return specificPrompts.map((makePrompt, i) => {
    const options = [d.correct, ...d.wrong].map((value, index, all) => all[(index + i) % all.length]);
    return { prompt:makePrompt(d), options, answer:options.indexOf(d.correct), why:d.why, code:i === 2 || i === 7 ? d.code : undefined };
  });
}

const definitions:Definition[] = [
 {id:"m04-declare",title:"declarar y llamar métodos",summary:"Un método encapsula una operación con nombre. Su firma combina nombre, parámetros y tipo de retorno; se invoca usando paréntesis.",code:"static int Sum(int a, int b) => a + b;\nvar total = Sum(2, 3);",correct:"Definir una operación reutilizable y llamarla con sus argumentos",wrong:["Crear siempre un objeto nuevo","Ejecutar código sin una firma","Convertir todo a dynamic"],why:"Los métodos permiten nombrar, reutilizar y probar una operación; la llamada debe respetar su firma."},
 {id:"m04-return",title:"parámetros y valores de retorno",summary:"Los parámetros reciben datos y return entrega un resultado. El tipo retornado debe coincidir con la firma, salvo conversiones válidas.",code:"static bool IsAdult(int age)\n    => age >= 18;",correct:"El método puede recibir parámetros y devolver un valor del tipo declarado",wrong:["Todo método debe devolver string","return solo sirve para loops","Los parámetros cambian de tipo en cada llamada"],why:"La firma comunica el contrato del método: entradas y salida."},
 {id:"m04-overload",title:"sobrecarga de métodos",summary:"La sobrecarga permite varios métodos con el mismo nombre si sus listas de parámetros son diferentes. El retorno por sí solo no distingue una sobrecarga.",code:"void Print(int value) {}\nvoid Print(string value) {}",correct:"Mismo nombre con parámetros diferentes",wrong:["Mismo nombre y solo retorno diferente","Dos métodos idénticos","Cambiar únicamente el nombre del archivo"],why:"El compilador selecciona la sobrecarga por cantidad, tipos y modificadores de parámetros; no por retorno."},
 {id:"m04-scope",title:"scope y variables locales",summary:"Una variable local existe dentro del bloque donde se declara y los bloques internos pueden usar nombres visibles de scopes externos.",code:"if (ready) { int local = 1; }\n// local no existe aquí",correct:"El nombre solo está disponible en su ámbito",wrong:["Toda variable local es global","El scope depende del valor","Una variable vive siempre toda la aplicación"],why:"Un scope pequeño evita usos accidentales y hace explícita la vida de los nombres."},
 {id:"m04-optional",title:"parámetros opcionales y nombrados",summary:"Los parámetros opcionales tienen un valor predeterminado. Los argumentos nombrados hacen explícita la asociación entre argumento y parámetro.",code:"void Connect(string host, int port = 443) {}\nConnect(host: \"api\");",correct:"Se puede omitir el parámetro opcional o llamarlo por nombre",wrong:["Todos los parámetros deben omitirse","El nombre es ignorado por el compilador","Los valores opcionales se calculan siempre en runtime"],why:"Los opcionales simplifican llamadas y los nombrados mejoran claridad, pero deben respetar las reglas de la firma."},
 {id:"m04-expression",title:"expression-bodied members",summary:"La sintaxis => permite expresar métodos, propiedades o constructores sencillos con una sola expresión.",code:"public int Double(int n) => n * 2;",correct:"Una forma compacta de escribir un miembro de una sola expresión",wrong:["Un lambda que siempre crea un thread","Una constante global","Una excepción automática"],why:"Expression-bodied es sintaxis; no cambia la semántica ni convierte el miembro en asíncrono."},
 {id:"m04-main",title:"el método Main",summary:"Main es un punto de entrada válido para una aplicación de consola. Puede devolver void o int y aceptar argumentos de línea de comandos.",code:"static void Main(string[] args)\n{\n    Console.WriteLine(\"Hi\");\n}",correct:"El punto de entrada de una aplicación de consola",wrong:["El constructor de toda clase","Un método que se ejecuta en cada request","Una interfaz obligatoria"],why:"El runtime usa Main como entrada cuando el proyecto no usa top-level statements."},
 {id:"m04-challenge",title:"reto de métodos",summary:"Integra firmas, sobrecarga, scope, retorno y argumentos para resolver pequeños problemas sin duplicar lógica.",code:"static int Add(int a, int b) => a + b;\nConsole.WriteLine(Add(4, 5));",correct:"Elegir una firma clara y reutilizable para resolver el problema",wrong:["Usar estado global para cada operación","Devolver object siempre","Evitar parámetros y repetir código"],why:"Un buen método tiene una responsabilidad clara, entradas explícitas y una salida verificable."},

 {id:"m05-create",title:"crear y concatenar strings",summary:"string representa texto y es inmutable. La concatenación crea un nuevo resultado; para muchas modificaciones conviene evaluar StringBuilder.",code:"var full = first + \" \" + last;",correct:"Construir una nueva cadena a partir de valores de texto",wrong:["Modificar chars de string en sitio","Convertir siempre a byte[]","Hacer que string sea mutable"],why:"Las operaciones de string producen nuevas cadenas porque string es inmutable."},
 {id:"m05-interpolation",title:"interpolación",summary:"La interpolación usa $ y expresiones entre llaves para construir texto legible, con formatos opcionales.",code:"var message = $\"Total: {total:C}\";",correct:"Insertar el valor de una expresión dentro de una cadena",wrong:["Escapar todo el contenido","Crear un char","Ejecutar SQL automáticamente"],why:"$ activa la interpolación; los formatos como :C se aplican al valor insertado."},
 {id:"m05-escape",title:"escape characters",summary:"Las secuencias de escape representan caracteres especiales como salto de línea, tabulación, comillas y barra invertida.",code:"Console.WriteLine(\"A\\nB\");",correct:"Representar un carácter especial dentro de un literal",wrong:["Convertir string en regex siempre","Eliminar la inmutabilidad","Indicar un comentario"],why:"\\n, \\t, \\\\ y \\\" tienen significados especiales en literales normales."},
 {id:"m05-compare",title:"comparar strings",summary:"La igualdad de strings compara contenido. Para ordenamiento y reglas culturales se debe elegir la comparación adecuada, a menudo con StringComparison.",code:"string.Equals(a, b, StringComparison.OrdinalIgnoreCase);",correct:"Comparar texto usando una regla explícita de igualdad",wrong:["Comparar siempre referencias con ReferenceEquals","Usar == solo para ordenar culturas","Convertir todo a char"],why:"La comparación de texto puede depender de mayúsculas, cultura y seguridad; especificar la intención evita errores."},
 {id:"m05-methods",title:"métodos de string",summary:"Length, Contains, StartsWith, Replace, Split y Substring consultan o transforman texto sin mutar la cadena original.",code:"var clean = input.Trim().ToLowerInvariant();",correct:"Cada operación devuelve un resultado y no muta el string original",wrong:["Todas cambian la cadena en sitio","Solo funcionan con ASCII","Devuelven siempre char"],why:"string es inmutable; encadenar métodos crea resultados intermedios o finales nuevos."},
 {id:"m05-parse",title:"Parse y TryParse",summary:"Parse convierte y lanza una excepción si el formato falla; TryParse devuelve false y entrega el valor por out.",code:"if (int.TryParse(text, out var number))\n    Console.WriteLine(number);",correct:"TryParse es preferible cuando la entrada puede ser inválida",wrong:["TryParse siempre lanza","Parse nunca falla","Cast convierte cualquier texto"],why:"TryParse permite manejar entrada inválida como una condición normal."},
 {id:"m05-builder",title:"StringBuilder",summary:"StringBuilder es útil para muchas modificaciones de texto porque mantiene un búfer mutable y evita crear tantas cadenas intermedias.",code:"var sb = new StringBuilder();\nsb.Append(\"A\").Append(\"B\");",correct:"Acumular muchas modificaciones de texto de forma eficiente",wrong:["Reemplazar todos los strings pequeños","Hacer texto inmutable","Serializar JSON automáticamente"],why:"StringBuilder es una herramienta de rendimiento; para pocas concatenaciones, string suele ser suficiente."},
 {id:"m05-challenge",title:"reto de strings",summary:"Combina limpieza, comparación, formato y parsing para procesar entradas de usuario de forma predecible.",code:"var input = \"  42 \".Trim();\nvar ok = int.TryParse(input, out var value);",correct:"Validar y transformar texto sin asumir que siempre tiene formato válido",wrong:["Usar Parse sin validar siempre","Comparar solo referencias","Mutar string por índice"],why:"El código robusto trata la entrada como datos potencialmente inválidos y conserva una intención clara."},

 {id:"m06-class",title:"qué es una clase",summary:"Una clase es un tipo de referencia que define estado y comportamiento. new crea una instancia y la variable contiene una referencia.",code:"class User { public string Name { get; set; } }\nvar user = new User();",correct:"Un molde de referencia para crear objetos con miembros",wrong:["Un valor primitivo","Una función global","Un namespace ejecutable"],why:"Las clases agrupan datos y operaciones; sus instancias viven como objetos y pueden compartir referencia."},
 {id:"m06-members",title:"campos y propiedades",summary:"Los campos almacenan datos directamente. Las propiedades exponen acceso controlado con get y set, y pueden validar o encapsular reglas.",code:"public string Name { get; private set; }",correct:"Una propiedad puede controlar cómo se lee o asigna un dato",wrong:["Una propiedad es siempre un campo público","get ejecuta el constructor","private set permite escribir desde cualquier lugar"],why:"Las propiedades son una frontera de encapsulación; un setter privado restringe la mutación externa."},
 {id:"m06-constructors",title:"constructores",summary:"Un constructor inicializa una instancia y se ejecuta al usar new. Puede estar sobrecargado y encadenarse con this o base.",code:"public User(string name) { Name = name; }",correct:"Inicializar el estado al crear un objeto",wrong:["Destruir el objeto","Ejecutarse una vez por aplicación","Ser heredado como un método normal"],why:"Los constructores no se heredan y preparan invariantes de la instancia."},
 {id:"m06-new",title:"crear objetos",summary:"new invoca un constructor y devuelve una instancia. Un inicializador de objeto puede asignar propiedades accesibles inmediatamente.",code:"var user = new User { Name = \"Ada\" };",correct:"Crear una instancia y opcionalmente inicializar propiedades",wrong:["Declarar una interfaz","Convertir una clase en static","Copiar siempre por valor"],why:"La expresión new crea el objeto; el inicializador asigna miembros después de construirlo."},
 {id:"m06-instances",title:"varias instancias",summary:"Cada instancia de una clase tiene su propio estado de instancia, mientras que los miembros static se comparten por el tipo.",code:"var a = new User();\nvar b = new User();\na.Name = \"Ada\";",correct:"Dos objetos pueden tener estados independientes",wrong:["Todas las instancias comparten cada campo","new devuelve siempre el mismo objeto","Las propiedades son globales"],why:"Los campos y propiedades de instancia pertenecen a cada objeto, no a todas las instancias."},
 {id:"m06-instance-methods",title:"métodos de instancia",summary:"Un método de instancia opera sobre el objeto actual y puede acceder a sus miembros mediante this, explícito o implícito.",code:"public void Rename(string name) => Name = name;",correct:"Un método que usa el estado de una instancia concreta",wrong:["Un método que solo puede usar static","Una propiedad automática","Un constructor obligatorio"],why:"Los métodos de instancia reciben implícitamente la instancia actual como contexto."},
 {id:"m06-challenge",title:"reto de clases",summary:"Diseña una clase con estado válido, propiedades protegidas y métodos que expresen las operaciones permitidas.",code:"var account = new Account(100);\naccount.Deposit(25);",correct:"Proteger invariantes y exponer operaciones claras",wrong:["Hacer todos los campos públicos","Permitir saldo negativo sin regla","Usar globales para cada objeto"],why:"Una clase útil protege su estado y ofrece una API pequeña que mantiene sus reglas."},

 {id:"m07-value-ref",title:"value types vs reference types",summary:"Los value types copian su valor al asignarse. Los reference types copian la referencia; dos variables pueden apuntar al mismo objeto.",code:"var a = new List<int>();\nvar b = a;\nb.Add(1);",correct:"Con una clase o lista, a y b pueden referirse al mismo objeto",wrong:["Siempre se copia toda la lista","List es un value type","Las referencias son siempre inmutables"],why:"La diferencia afecta copias, aliasing y mutaciones observables."},
 {id:"m07-pass-value",title:"pasar parámetros por valor",summary:"Por defecto, C# pasa parámetros por valor. En reference types se copia la referencia, por lo que el método aún puede mutar el objeto apuntado.",code:"void Add(List<int> xs) => xs.Add(1);",correct:"Se copia la referencia, no el objeto completo",wrong:["Todo parámetro se pasa por referencia con ref","Nunca se puede mutar el objeto","Se clona la lista automáticamente"],why:"Pasar una referencia por valor permite mutar el objeto, pero reasignar el parámetro no cambia la variable del llamador."},
 {id:"m07-ref-out-in",title:"ref, out e in",summary:"ref requiere una variable inicializada antes de la llamada; out no requiere inicialización previa, pero el método debe asignarle un valor; in pasa una referencia de solo lectura.",code:"int value = 0;\nUpdate(ref value);\nint.TryParse(text, out var number);",correct:"ref recibe una variable inicializada y out puede recibir una variable no inicializada",wrong:["out exige valor inicial","ref ignora la variable del llamador","in permite modificar el argumento"],why:"ref se usa para leer y modificar una variable existente; out se usa para producir un valor y obliga al método a asignarlo antes de terminar."},
 {id:"m07-string-ref",title:"strings como reference types",summary:"string es reference type, pero su inmutabilidad hace que operaciones como concatenar devuelvan una nueva cadena en lugar de alterar la anterior.",code:"var a = \"A\";\nvar b = a;\nb += \"B\";",correct:"b recibe una nueva string y a permanece \"A\"",wrong:["a cambia a \"AB\" siempre","string es value type","b modifica chars internos"],why:"La referencia se copia, pero el objeto string no se modifica; se crea otro valor de texto."},
 {id:"m07-enums",title:"enums",summary:"Un enum define nombres para un conjunto de valores integrales. Puede convertirse a su tipo subyacente, pero conviene validar valores externos.",code:"enum Status { Draft, Published }\nStatus s = Status.Draft;",correct:"Nombrar estados relacionados de forma tipada",wrong:["Guardar cualquier texto sin validación","Crear herencia múltiple","Reemplazar todas las clases"],why:"Los enums mejoran legibilidad, aunque sus valores subyacentes pueden contener números no declarados."},
 {id:"m07-structs",title:"structs",summary:"Un struct es un value type apropiado para datos pequeños cuyo valor representa la entidad. No admite herencia de clases, pero puede implementar interfaces.",code:"readonly struct Point(int x, int y);",correct:"Un tipo de valor que se copia y puede implementar interfaces",wrong:["Una clase con herencia completa","Siempre mejor que class","Un reference type mutable por defecto"],why:"Elegir struct requiere considerar tamaño, copias, mutabilidad y semántica de valor."},
 {id:"m07-nullable",title:"nullable value types",summary:"T? para un value type permite representar un valor o null. HasValue y Value, o pattern matching, permiten acceder con seguridad.",code:"int? age = null;\nvar text = age?.ToString() ?? \"unknown\";",correct:"int? puede contener un entero o null",wrong:["int ya contiene null siempre","T? elimina todos los null","Nullable solo sirve para strings"],why:"Nullable<T> modela la ausencia de un value type sin inventar un valor especial."},
 {id:"m07-challenge",title:"reto de memoria",summary:"Predice copias, aliasing, boxing y nullability para evitar sorpresas al pasar valores y referencias entre métodos.",code:"int x = 1;\nvar y = x;\ny++;\nConsole.WriteLine(x);",correct:"Analizar si se copió el valor o la referencia antes de predecir el resultado",wrong:["Asumir que todo se comparte","Asumir que todo se clona","Ignorar nullability"],why:"La semántica de copia depende del tipo; es una pregunta clásica de entrevistas."},

 {id:"m08-namespace",title:"namespaces y using",summary:"Los namespaces organizan nombres y reducen colisiones. using permite referirse a tipos sin escribir siempre su nombre completamente calificado.",code:"using System.Collections.Generic;\nList<int> values = [];",correct:"Organizar tipos y simplificar sus nombres en un archivo",wrong:["Importar paquetes npm","Crear una instancia","Hacer un método async"],why:"using no copia ni ejecuta código; resuelve nombres de tipos y puede declarar disposiciones."},
 {id:"m08-static",title:"clases y miembros static",summary:"Un miembro static pertenece al tipo, no a una instancia. Una static class no puede instanciarse y solo contiene miembros static.",code:"static class MathTools { public static int Twice(int n) => n * 2; }",correct:"Acceder a un miembro a través del tipo sin crear instancia",wrong:["Compartir automáticamente todos los campos de instancia","Permitir herencia de static class","Guardar estado por usuario"],why:"static es apropiado para comportamiento sin estado de instancia; el estado global debe usarse con cuidado."},
 {id:"m08-null",title:"null y nullable reference types",summary:"null indica ausencia de referencia. Las anotaciones nullable ayudan al compilador a advertir posibles null, pero no agregan validación runtime por sí solas.",code:"string? name = null;\nConsole.WriteLine(name?.Length);",correct:"? expresa que una referencia puede ser null y ?. evita acceso directo",wrong:["? garantiza que nunca será null","null es un string vacío","El compilador lanza todas las excepciones"],why:"Nullable reference types son análisis estático; el programa aún debe validar entradas en runtime."},
 {id:"m08-gc",title:"garbage collection",summary:"El GC administra memoria de objetos administrados y recupera objetos que ya no son alcanzables. No reemplaza liberar recursos externos como archivos.",code:"using var stream = File.OpenRead(path);",correct:"El GC recupera memoria administrada, pero IDisposable maneja recursos externos",wrong:["GC cierra siempre sockets inmediatamente","GC elimina toda memoria nativa","GC se ejecuta al llamar Collect únicamente"],why:"La memoria y los recursos externos tienen ciclos de vida diferentes; using/Dispose es determinista."},
 {id:"m08-library",title:"class libraries",summary:"Una class library empaqueta tipos reutilizables en un ensamblado, normalmente DLL, que otros proyectos pueden referenciar.",code:"dotnet new classlib -n Shared\ndotnet add App reference Shared",correct:"Separar código reutilizable para referenciarlo desde otros proyectos",wrong:["Crear una base de datos","Publicar solo una página HTML","Reemplazar el runtime"],why:"Las librerías permiten compartir dominio, utilidades o contratos sin duplicar código."},
 {id:"m08-records",title:"records y record structs",summary:"Los records ofrecen igualdad por valor, una representación útil para datos y sintaxis with. record class es referencia; record struct es valor.",code:"public record User(int Id, string Name);\nvar copy = user with { Name = \"Lin\" };",correct:"Modelar datos con igualdad basada en valores y copias no destructivas",wrong:["Obtener herencia de structs","Hacer todas las propiedades mutables","Comparar siempre por referencia"],why:"Records reducen código ceremonial para modelos de datos y expresan semántica de valor."},
 {id:"m08-compare",title:"class vs struct vs record",summary:"class suele modelar identidad y referencia; struct valores pequeños; record datos cuya igualdad depende del contenido. La elección es semántica, no de moda.",code:"class Entity { public int Id; }\nrecord Point(int X, int Y);",correct:"Elegir según identidad, semántica de valor, tamaño y mutabilidad",wrong:["record siempre reemplaza class","struct siempre es más rápido","class y struct son idénticos"],why:"La diferencia afecta igualdad, copias, herencia y comportamiento de memoria."},
 {id:"m08-challenge",title:"reto de diseño de tipos",summary:"Selecciona class, struct, record o static con una razón explícita: identidad, datos, tamaño, ciclo de vida y comportamiento.",code:"public record Money(decimal Amount, string Currency);",correct:"Usar un record cuando la igualdad por datos expresa el dominio",wrong:["Usar static para cada modelo","Usar struct mutable gigante","Elegir por el nombre solamente"],why:"Un tipo comunica reglas del dominio; la semántica correcta evita bugs de igualdad y mutación."},

 {id:"m09-array",title:"arrays unidimensionales",summary:"Un array tiene longitud fija y almacena elementos del mismo tipo. Sus índices comienzan en cero y se accede con [] .",code:"int[] values = [10, 20, 30];\nConsole.WriteLine(values[0]);",correct:"Una colección indexada de tamaño fijo",wrong:["Una lista cuyo tamaño cambia automáticamente","Un diccionario por clave","Un conjunto sin orden"],why:"Los arrays son simples y eficientes cuando el tamaño o la estructura es conocida."},
 {id:"m09-multi",title:"arrays multidimensionales",summary:"Los arrays rectangulares y dentados representan distintas estructuras. Un array dentado es un array cuyos elementos son otros arrays.",code:"int[,] matrix = new int[2, 3];\nint[][] jagged = [ [1], [2, 3] ];",correct:"[,] representa rectangular y [][] representa dentado",wrong:["Ambos son exactamente lo mismo","[,] es un Dictionary","[][] no puede variar por fila"],why:"La sintaxis comunica si todas las filas comparten dimensiones o si cada fila puede variar."},
 {id:"m09-list",title:"List<T>",summary:"List<T> es una colección genérica redimensionable e indexada. Add, Remove y Contains operan sobre sus elementos según igualdad.",code:"var numbers = new List<int> { 1, 2 };\nnumbers.Add(3);",correct:"Una secuencia ordenada que puede crecer y admite índice",wrong:["Una clave única sin duplicados","Un array de longitud fija","Un stream asíncrono"],why:"List<T> es una opción general para colecciones ordenadas y mutables."},
 {id:"m09-dictionary",title:"Dictionary<TKey,TValue>",summary:"Dictionary asocia claves únicas con valores y ofrece búsquedas por clave. TryGetValue evita asumir que una clave existe.",code:"var ages = new Dictionary<string,int>();\nages[\"Ada\"] = 36;",correct:"Buscar un valor mediante una clave única",wrong:["Permitir claves duplicadas sin regla","Ordenar siempre por valor","Acceder solo por índice entero"],why:"La clave identifica el valor; conviene decidir cómo manejar claves ausentes y duplicadas."},
 {id:"m09-hashset",title:"HashSet<T>",summary:"HashSet representa un conjunto de elementos únicos y está optimizado para pertenencia. No debe usarse si el orden o duplicados son esenciales.",code:"var tags = new HashSet<string>();\ntags.Add(\"csharp\");",correct:"Mantener elementos sin duplicados y consultar pertenencia",wrong:["Conservar duplicados en orden de inserción garantizado","Mapear claves a valores","Indexar por posición"],why:"HashSet expresa semántica de conjunto y usa igualdad/hash del tipo."},
 {id:"m09-enumerable",title:"IEnumerable<T>",summary:"IEnumerable<T> representa algo que puede enumerarse. Muchas operaciones LINQ sobre él son diferidas hasta que se recorre o materializa.",code:"IEnumerable<int> query = values.Where(x => x > 0);",correct:"Una secuencia que puede recorrerse con foreach",wrong:["Una base de datos obligatoria","Una lista siempre materializada","Un tipo que permite indexar siempre"],why:"IEnumerable no garantiza índice ni evaluación inmediata; expresa capacidad de enumeración."},
 {id:"m09-choice",title:"elegir la colección correcta",summary:"La colección se elige por acceso, unicidad, orden, mutabilidad y rendimiento esperado, no solo por costumbre.",code:"Dictionary<int,User> byId = ...;\nList<User> ordered = ...;",correct:"Seleccionar List, Dictionary, HashSet o array según la operación dominante",wrong:["Usar List para toda búsqueda por clave","Usar HashSet cuando importan duplicados","Usar array cuando el tamaño cambia mucho"],why:"La estructura correcta hace explícita la intención y evita trabajo innecesario."},
 {id:"m09-challenge",title:"reto de colecciones",summary:"Combina índices, claves, unicidad y enumeración para modelar datos reales y elegir operaciones seguras.",code:"if (byId.TryGetValue(id, out var user))\n    Console.WriteLine(user.Name);",correct:"Usar la operación que expresa la garantía que necesitas",wrong:["Acceder a cualquier clave sin comprobar","Eliminar duplicados siempre","Convertir todo a object"],why:"Las colecciones tienen contratos distintos; las preguntas de entrevista suelen explorar esas diferencias."},

 {id:"m10-oop",title:"principios de orientación a objetos",summary:"La POO organiza estado y comportamiento en tipos. Encapsulación, abstracción, herencia y polimorfismo son ideas relacionadas, no simples palabras clave.",code:"public abstract class Shape { public abstract double Area(); }",correct:"Modelar responsabilidades y colaboraciones entre objetos",wrong:["Usar una clase por cada variable","Hacer todo heredable","Evitar contratos y pruebas"],why:"La POO es una forma de organizar el diseño; una buena solución evita acoplamiento accidental."},
 {id:"m10-encapsulation",title:"encapsulación",summary:"Encapsular es proteger invariantes y ocultar detalles internos, exponiendo operaciones o propiedades que mantengan reglas válidas.",code:"private decimal balance;\npublic void Deposit(decimal amount) { if (amount > 0) balance += amount; }",correct:"Controlar cómo cambia el estado interno",wrong:["Hacer todos los campos public","Ocultar el nombre de la clase","Usar herencia para cada regla"],why:"La encapsulación concentra validaciones y evita que cualquier consumidor rompa el estado."},
 {id:"m10-access",title:"private, protected e internal",summary:"private limita al tipo; protected incluye derivados; internal permite el mismo ensamblado. public expone a cualquier consumidor permitido.",code:"protected void Reset() {}\ninternal class Helper {}",correct:"Elegir el modificador según quién debe acceder",wrong:["protected significa público","internal significa accesible desde Internet","private permite cualquier clase"],why:"Los modificadores de acceso son parte del diseño y reducen superficie accidental."},
 {id:"m10-inheritance",title:"herencia",summary:"Una clase derivada reutiliza y especializa una clase base. C# permite una sola clase base directa, aunque sí múltiples interfaces.",code:"class Dog : Animal { }",correct:"Expresar una relación Is-A y reutilizar comportamiento base",wrong:["Compartir estado sin relación","Heredar de varias clases base","Convertir composición en interfaz"],why:"La herencia debe representar especialización real; si no, composición suele ser más flexible."},
 {id:"m10-derived",title:"base y derived classes",summary:"La clase derivada puede llamar al constructor base con base(...), usar miembros protegidos y sobrescribir miembros virtuales con override.",code:"class Dog : Animal { public Dog() : base(\"dog\") {} }",correct:"Inicializar la parte base y extender el comportamiento derivado",wrong:["Heredar constructores automáticamente","Acceder a private base directamente","Sobrescribir sin virtual o abstract"],why:"Los constructores no se heredan y la visibilidad controla qué puede usar la clase derivada."},
 {id:"m10-isa",title:"relación Is-A",summary:"Is-A describe sustitución: un objeto derivado puede usarse donde se espera su base. Has-A describe composición y no debe confundirse.",code:"Animal animal = new Dog();\nanimal.Speak();",correct:"Un Dog es un Animal y puede sustituirlo en ese contrato",wrong:["Un Dog contiene un Animal siempre","Todo campo implica herencia","Is-A significa igualdad"],why:"La relación Is-A es conceptual y debe ser válida para todos los casos del dominio."},
 {id:"m10-composition",title:"composition over inheritance",summary:"La composición construye objetos combinando colaboradores. Suele reducir acoplamiento y permite cambiar comportamiento por inyección.",code:"class Car { private readonly IEngine engine; }",correct:"Un Car tiene un motor y delega responsabilidades",wrong:["Car hereda de Engine siempre","Composition significa static","Solo sirve para structs"],why:"La composición expresa Has-A y facilita reemplazar una dependencia sin cambiar jerarquías."},
 {id:"m10-challenge",title:"reto de encapsulación",summary:"Diseña un pequeño modelo decidiendo qué ocultar, qué exponer y cuándo usar herencia, interfaz o composición.",code:"public sealed class Invoice\n{\n    public decimal Total { get; private set; }\n}",correct:"Exponer un contrato pequeño y proteger las invariantes",wrong:["Publicar todos los detalles internos","Usar herencia por defecto","Permitir mutación sin validación"],why:"El diseño OO se evalúa por responsabilidades, acoplamiento y facilidad de cambio, no por cantidad de clases."},
];

